CREATE OR REPLACE FUNCTION zhiqing_rag.check_document_publish()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE g zhiqing_rag.index_generation%ROWTYPE; actual_count BIGINT; missing_vectors BIGINT;
BEGIN
    IF NEW.status = 'PUBLISHED' AND (
        TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status
        OR OLD.active_generation_id IS DISTINCT FROM NEW.active_generation_id
    ) THEN
        SELECT * INTO g FROM zhiqing_rag.index_generation
        WHERE tenant_id=NEW.tenant_id AND document_id=NEW.id AND id=NEW.active_generation_id
        FOR SHARE;
        IF NOT FOUND OR g.status <> 'READY' OR g.revision_id IS DISTINCT FROM NEW.desired_revision_id THEN
            RAISE EXCEPTION 'Published generation must be READY and match desired revision' USING ERRCODE='23514';
        END IF;
        SELECT count(*), count(*) FILTER (WHERE embedding IS NULL)
        INTO actual_count, missing_vectors FROM zhiqing_rag.document_chunk
        WHERE tenant_id=NEW.tenant_id AND generation_id=g.id;
        IF actual_count <> g.chunk_count OR actual_count=0 OR missing_vectors<>0 THEN
            RAISE EXCEPTION 'Generation chunk count or embeddings incomplete' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zhiqing_rag.check_evaluation_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE frozen_hash TEXT; current_state TEXT; actual_count BIGINT;
BEGIN
    SELECT dataset_sha256,status INTO frozen_hash,current_state FROM zhiqing_rag.evaluation_dataset
        WHERE tenant_id=NEW.tenant_id AND id=NEW.dataset_id FOR SHARE;
    IF current_state IS DISTINCT FROM 'FROZEN' OR frozen_hash IS DISTINCT FROM NEW.dataset_sha256 THEN
        RAISE EXCEPTION 'Evaluation requires a matching frozen dataset' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO actual_count FROM zhiqing_rag.evaluation_case WHERE tenant_id=NEW.tenant_id AND dataset_id=NEW.dataset_id;
    IF actual_count <> NEW.total_cases THEN
        RAISE EXCEPTION 'Evaluation case count mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zhiqing_rag.guard_chunk_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t BIGINT; gid BIGINT; current_state TEXT;
BEGIN
    IF TG_OP='DELETE' THEN t:=OLD.tenant_id; gid:=OLD.generation_id;
    ELSE t:=NEW.tenant_id; gid:=NEW.generation_id; END IF;
    IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.generation_id,NEW.document_id,NEW.revision_id,NEW.kb_id)
        IS DISTINCT FROM (OLD.tenant_id,OLD.generation_id,OLD.document_id,OLD.revision_id,OLD.kb_id) THEN
        RAISE EXCEPTION 'Chunk ownership is immutable' USING ERRCODE='23514';
    END IF;
    SELECT status INTO current_state FROM zhiqing_rag.index_generation
        WHERE tenant_id=t AND id=gid FOR UPDATE;
    IF TG_OP IN ('INSERT','UPDATE') AND current_state IS DISTINCT FROM 'BUILDING' THEN
        RAISE EXCEPTION 'Only BUILDING generations accept chunk writes' USING ERRCODE='23514';
    END IF;
    IF TG_OP='DELETE' AND EXISTS (
        SELECT 1 FROM zhiqing_rag.document WHERE tenant_id=t AND active_generation_id=gid
    ) THEN
        RAISE EXCEPTION 'Active generation cannot be cleaned' USING ERRCODE='23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zhiqing_rag.guard_evaluation_case()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t BIGINT; ds BIGINT; current_state TEXT;
BEGIN
    IF TG_OP='DELETE' THEN t:=OLD.tenant_id; ds:=OLD.dataset_id;
    ELSE t:=NEW.tenant_id; ds:=NEW.dataset_id; END IF;
    IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.dataset_id) IS DISTINCT FROM (OLD.tenant_id,OLD.dataset_id) THEN
        RAISE EXCEPTION 'Evaluation case ownership is immutable' USING ERRCODE='23514';
    END IF;
    SELECT status INTO current_state FROM zhiqing_rag.evaluation_dataset WHERE tenant_id=t AND id=ds FOR UPDATE;
    IF current_state IS DISTINCT FROM 'DRAFT' THEN
        RAISE EXCEPTION 'Only DRAFT datasets accept case changes' USING ERRCODE='23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zhiqing_rag.guard_generation_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_count BIGINT; missing_vectors BIGINT;
BEGIN
    IF (NEW.tenant_id,NEW.document_id,NEW.revision_id,NEW.embedding_profile_id,NEW.generation_no,
        NEW.parser_version,NEW.cleaner_version,NEW.chunker_version,NEW.chunk_config)
       IS DISTINCT FROM
       (OLD.tenant_id,OLD.document_id,OLD.revision_id,OLD.embedding_profile_id,OLD.generation_no,
        OLD.parser_version,OLD.cleaner_version,OLD.chunker_version,OLD.chunk_config) THEN
        RAISE EXCEPTION 'Generation identity and build configuration are immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.status <> 'BUILDING' AND (NEW.status,NEW.chunk_count,NEW.ready_at)
       IS DISTINCT FROM (OLD.status,OLD.chunk_count,OLD.ready_at) THEN
        RAISE EXCEPTION 'Completed generation cannot return to building or change results' USING ERRCODE='23514';
    END IF;
    IF OLD.status='BUILDING' AND NEW.status='READY' THEN
        SELECT count(*), count(*) FILTER (WHERE embedding IS NULL)
            INTO actual_count,missing_vectors FROM zhiqing_rag.document_chunk
            WHERE tenant_id=NEW.tenant_id AND generation_id=NEW.id;
        IF actual_count=0 OR actual_count<>NEW.chunk_count OR missing_vectors<>0 THEN
            RAISE EXCEPTION 'Cannot mark incomplete generation READY' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $function$
